import { loadConfig } from './config.js';
import { EXIT_CODES, TodoError, UsageError } from './errors.js';
import { escapeControlCharacters, formatTodoList } from './format.js';
import { loadState, resolveTodoFile, updateState } from './storage.js';
import { addTodo, completeTodo, deleteTodo, normalizeText, parseId } from './todos.js';

export const USAGE = `Usage: node index.js <command> [arguments]

Commands:
  add <text>       Add a new todo (quotes optional: add Buy milk)
  list             Show all todos with their status
  complete <id>    Mark a todo as done
  delete <id>      Remove a todo
  help             Show this message

Todos are stored in ./todos.json.`;

function describeTodo(todo) {
  return `todo ${todo.id}: ${escapeControlCharacters(todo.text)}`;
}

function requireNoArguments(command, args) {
  if (args.length > 0) {
    throw new UsageError(`"${command}" does not take arguments.`);
  }
}

function requireSingleId(command, args) {
  if (args.length === 0) {
    throw new UsageError(`Missing todo id. Usage: node index.js ${command} <id>`);
  }
  if (args.length > 1) {
    throw new UsageError(`Too many arguments for "${command}": expected one id, got ${args.length}.`);
  }
  return parseId(args[0]);
}

async function addCommand(args, context) {
  if (args.length === 0) {
    throw new UsageError('Missing todo text. Usage: node index.js add "Buy groceries"');
  }
  // Validate before taking the lock so bad input is reported even when the file is busy or corrupt.
  const text = normalizeText(args.join(' '), { maxLength: context.config.maxTextLength });
  const { todo } = await updateState(
    context.filePath,
    (state) => addTodo(state, text, { now: context.now(), maxTextLength: context.config.maxTextLength }),
    context.lockOptions,
  );
  return `Added ${describeTodo(todo)}`;
}

async function listCommand(args, context) {
  requireNoArguments('list', args);
  const { todos } = await loadState(context.filePath);
  return formatTodoList(todos);
}

async function completeCommand(args, context) {
  const id = requireSingleId('complete', args);
  const { todo, changed } = await updateState(context.filePath, (state) => completeTodo(state, id), context.lockOptions);
  return changed ? `Completed ${describeTodo(todo)}` : `Todo ${todo.id} is already completed: ${escapeControlCharacters(todo.text)}`;
}

async function deleteCommand(args, context) {
  const id = requireSingleId('delete', args);
  const { todo } = await updateState(context.filePath, (state) => deleteTodo(state, id), context.lockOptions);
  return `Deleted ${describeTodo(todo)}`;
}

async function helpCommand() {
  return USAGE;
}

const COMMANDS = new Map([
  ['add', addCommand],
  ['list', listCommand],
  ['complete', completeCommand],
  ['delete', deleteCommand],
  ['help', helpCommand],
  ['--help', helpCommand],
  ['-h', helpCommand],
]);

function reportError(error, stderr) {
  if (error instanceof TodoError) {
    stderr.write(`Error: ${error.message}\n`);
    if (error instanceof UsageError) {
      stderr.write(`\n${USAGE}\n`);
    }
    return error.exitCode;
  }
  stderr.write(`Unexpected error (this is a bug): ${error?.stack ?? String(error)}\n`);
  return EXIT_CODES.FAILURE;
}

/**
 * Runs one CLI invocation and resolves with the process exit code. Never
 * throws: expected failures go to `stderr` as a one-line message, unexpected
 * ones with their stack trace.
 *
 * @param {string[]} argv Arguments after `node index.js`.
 * @param {object} [options] Injection points for tests.
 * @param {string} [options.cwd] Directory holding todos.json.
 * @param {Record<string, string | undefined>} [options.env] Source of `TODO_*` limits.
 * @param {{ write(chunk: string): unknown }} [options.stdout]
 * @param {{ write(chunk: string): unknown }} [options.stderr]
 * @param {() => Date} [options.now] Clock used for `createdAt`.
 * @returns {Promise<number>}
 */
export async function run(
  argv,
  {
    cwd = process.cwd(),
    env = process.env,
    stdout = process.stdout,
    stderr = process.stderr,
    now = () => new Date(),
  } = {},
) {
  try {
    const config = loadConfig(env);
    const [commandName, ...args] = argv;
    if (commandName === undefined) {
      throw new UsageError('No command given.');
    }
    const command = COMMANDS.get(commandName);
    if (command === undefined) {
      throw new UsageError(`Unknown command "${escapeControlCharacters(commandName)}".`);
    }
    const output = await command(args, {
      filePath: resolveTodoFile(cwd),
      config,
      now,
      lockOptions: { timeoutMs: config.lockTimeoutMs, staleLockMs: config.staleLockMs },
    });
    stdout.write(`${output}\n`);
    return EXIT_CODES.SUCCESS;
  } catch (error) {
    return reportError(error, stderr);
  }
}
import { DEFAULT_MAX_TEXT_LENGTH } from './config.js';
import { NotFoundError, StorageError, ValidationError } from './errors.js';
import { escapeControlCharacters } from './format.js';

const CONTROL_CHARACTER = /\p{Cc}/u;
const DIGITS_ONLY = /^\d+$/;
const MAX_ID_ECHO_LENGTH = 40;

/**
 * State shape shared by every operation: `nextId` is the id the next `add`
 * will use. It only grows, so ids of deleted todos are never handed out again.
 */
export function createEmptyState() {
  return { nextId: 1, todos: [] };
}

/**
 * Trims `rawText` and checks it is non-empty, single-line, and at most
 * `maxLength` Unicode code points (not UTF-16 units, so an emoji counts as one).
 */
export function normalizeText(rawText, { maxLength = DEFAULT_MAX_TEXT_LENGTH } = {}) {
  if (typeof rawText !== 'string') {
    throw new ValidationError(`Todo text must be a string, got ${typeof rawText}.`);
  }
  const text = rawText.trim();
  if (text.length === 0) {
    throw new ValidationError('Todo text cannot be empty or only whitespace.');
  }
  if (CONTROL_CHARACTER.test(text)) {
    throw new ValidationError('Todo text must be a single line without control characters such as newlines or tabs.');
  }
  const length = [...text].length;
  if (length > maxLength) {
    throw new ValidationError(`Todo text is too long (${length} characters; the maximum is ${maxLength}).`);
  }
  return text;
}

function describeRawId(rawId) {
  const display = escapeControlCharacters(String(rawId));
  const truncated = [...display].length > MAX_ID_ECHO_LENGTH
    ? `${[...display].slice(0, MAX_ID_ECHO_LENGTH).join('')}…`
    : display;
  return `"${truncated}"`;
}

/** Parses a user-supplied id. Accepts only decimal digits that form a safe integer ≥ 1. */
export function parseId(rawId) {
  const text = String(rawId);
  const id = Number(text);
  if (!DIGITS_ONLY.test(text) || !Number.isSafeInteger(id) || id < 1) {
    throw new ValidationError(`Invalid id ${describeRawId(rawId)}: expected a positive whole number such as 1 or 42.`);
  }
  return id;
}

function findTodoIndex(state, id) {
  const index = state.todos.findIndex((todo) => todo.id === id);
  if (index === -1) {
    throw new NotFoundError(`No todo with id ${id}. Run "node index.js list" to see existing ids.`);
  }
  return index;
}

/** Returns `{ state, todo }` with a new pending todo appended. */
export function addTodo(state, rawText, { now = new Date(), maxTextLength } = {}) {
  const text = normalizeText(rawText, { maxLength: maxTextLength });
  const id = state.nextId;
  if (!Number.isSafeInteger(id + 1)) {
    throw new StorageError(`Cannot add a todo: the id counter (${id}) has reached the largest supported value.`);
  }
  const todo = { id, text, completed: false, createdAt: now.toISOString() };
  return {
    state: { nextId: id + 1, todos: [...state.todos, todo] },
    todo,
  };
}

/**
 * Returns `{ state, todo, changed }`. Completing an already completed todo is
 * a no-op (`changed: false`, same `state` object) rather than an error.
 */
export function completeTodo(state, id) {
  const index = findTodoIndex(state, id);
  const existing = state.todos[index];
  if (existing.completed) {
    return { state, todo: existing, changed: false };
  }
  const todo = { ...existing, completed: true };
  return {
    state: { ...state, todos: state.todos.with(index, todo) },
    todo,
    changed: true,
  };
}

/** Returns `{ state, todo }` where `todo` is the removed item. `nextId` is left unchanged. */
export function deleteTodo(state, id) {
  const index = findTodoIndex(state, id);
  return {
    state: { ...state, todos: state.todos.toSpliced(index, 1) },
    todo: state.todos[index],
  };
}
/** Process exit codes: 0 success, 1 the command failed, 2 the command was called incorrectly. */
export const EXIT_CODES = Object.freeze({
  SUCCESS: 0,
  FAILURE: 1,
  USAGE: 2,
});

/**
 * Base class for expected failures. The CLI prints `message` without a stack
 * trace and exits with `exitCode`; anything else is treated as a bug.
 */
export class TodoError extends Error {
  constructor(message, { exitCode = EXIT_CODES.FAILURE, cause } = {}) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = new.target.name;
    this.exitCode = exitCode;
  }
}

/** Wrong command shape: unknown command, missing or extra arguments. Usage is printed. */
export class UsageError extends TodoError {
  constructor(message, options = {}) {
    super(message, { ...options, exitCode: EXIT_CODES.USAGE });
  }
}

/** An argument has the right position but an unacceptable value, such as an id of "abc". */
export class ValidationError extends TodoError {
  constructor(message, options = {}) {
    super(message, { ...options, exitCode: EXIT_CODES.USAGE });
  }
}

/** The referenced todo does not exist. */
export class NotFoundError extends TodoError {}

/** todos.json (or its lock) could not be read, parsed, validated, or written. */
export class StorageError extends TodoError {}
const CONTROL_CHARACTER = /\p{Cc}/gu;

/**
 * Replaces control characters (newlines, tabs, ESC, C1 controls) with visible
 * `\uXXXX` escapes. Text written by `add` never contains them, but a
 * hand-edited todos.json might, and printing raw ESC sequences would let file
 * contents drive the terminal.
 */
export function escapeControlCharacters(text) {
  return text.replace(CONTROL_CHARACTER, (char) => `\\u${char.codePointAt(0).toString(16).padStart(4, '0')}`);
}

function pluralize(count, singular, plural) {
  return `${count} ${count === 1 ? singular : plural}`;
}

/** Renders one todo as `<id>. [x] <text>`, padding the id column to `idWidth` digits. */
export function formatTodoLine(todo, idWidth = String(todo.id).length) {
  const idLabel = `${todo.id}.`.padEnd(idWidth + 1);
  const status = todo.completed ? '[x]' : '[ ]';
  return `${idLabel} ${status} ${escapeControlCharacters(todo.text)}`;
}

/** Renders the `list` output: one line per todo in id order, then a done/pending summary. */
export function formatTodoList(todos) {
  if (todos.length === 0) {
    return 'No todos yet. Add one with: node index.js add "Buy groceries"';
  }

  const sorted = todos.toSorted((a, b) => a.id - b.id);
  const idWidth = sorted.reduce((width, todo) => Math.max(width, String(todo.id).length), 0);
  const doneCount = sorted.filter((todo) => todo.completed).length;
  const pendingCount = sorted.length - doneCount;

  const lines = sorted.map((todo) => formatTodoLine(todo, idWidth));
  lines.push('', `${pluralize(sorted.length, 'todo', 'todos')}: ${doneCount} done, ${pendingCount} pending`);
  return lines.join('\n');
}
# cli-todo-app

A command-line todo list for Node.js. Todos live in `todos.json` in the directory you run the command from. There are no runtime dependencies.

## Requirements

Node.js 22 or later.

## Usage

```console
$ node index.js add "Buy groceries"
Added todo 1: Buy groceries

$ node index.js add Walk the dog          # quotes are optional
Added todo 2: Walk the dog

$ node index.js complete 1
Completed todo 1: Buy groceries

$ node index.js list
1. [x] Buy groceries
2. [ ] Walk the dog

2 todos: 1 done, 1 pending

$ node index.js delete 2
Deleted todo 2: Walk the dog
```

| Command | Effect |
| --- | --- |
| `add <text>` | Adds a pending todo. Several unquoted words are joined with single spaces. |
| `list` | Prints every todo as `<id>. [x] <text>` (done) or `<id>. [ ] <text>` (pending), sorted by id, then a summary line. An empty list prints a hint instead. |
| `complete <id>` | Marks the todo done. Completing a todo that is already done prints a note and exits 0. |
| `delete <id>` | Removes the todo. |
| `help`, `--help`, `-h` | Prints usage. |

Output goes to stdout; errors go to stderr as a single `Error: ...` line. Usage errors are followed by the usage text.

### Exit codes

| Code | Meaning | Examples |
| --- | --- | --- |
| 0 | Success | Any successful command, including `list` on an empty list |
| 1 | The command could not be carried out | No todo with that id; `todos.json` is corrupt or unreadable; lock timeout |
| 2 | The command was called incorrectly | No command, unknown command, missing or extra arguments, an id like `abc` or `0`, empty or too-long text, a malformed `TODO_*` variable |

### Configuration

| Variable | Default | Purpose |
| --- | --- | --- |
| `TODO_MAX_TEXT_LENGTH` | `500` | Maximum todo length, in Unicode code points |
| `TODO_LOCK_TIMEOUT_MS` | `5000` | How long a write waits for another command to release the lock |
| `TODO_STALE_LOCK_MS` | `10000` | Age after which a leftover lock file is treated as abandoned and removed |

Each must be a positive whole number. Any other value is rejected with exit code 2; it is not silently ignored.

## Storage format

```json
{
  "nextId": 4,
  "todos": [
    { "id": 1, "text": "Buy groceries", "completed": true, "createdAt": "2026-09-30T11:47:02.261Z" },
    { "id": 3, "text": "Call mom", "completed": false, "createdAt": "2026-09-30T11:47:03.393Z" }
  ]
}
```

Every todo has exactly the four required fields: `id` (integer), `text`, `completed` (boolean), `createdAt` (ISO 8601). `nextId` is the id the next `add` will use.

A file that holds a bare array of todos is also accepted, so a hand-written or older file still works. It is rewritten in the object format on the next change.

## Design decisions

### Module layout

| File | Responsibility |
| --- | --- |
| `index.js` | Entry point. Passes `process.argv` to `run`, sets the exit code, and handles process-level concerns such as a closed stdout pipe. |
| `src/cli.js` | Argument checks, command dispatch, turning errors into messages and exit codes. `run(argv, options)` accepts `cwd`, `env`, `stdout`, `stderr`, and `now`, so tests can drive it in-process. |
| `src/todos.js` | Pure state operations (`addTodo`, `completeTodo`, `deleteTodo`) and input validation (`normalizeText`, `parseId`). No I/O. Each operation returns a new state object and leaves its input untouched. |
| `src/storage.js` | Reading, validating, and atomically writing `todos.json`, plus the lock. |
| `src/format.js` | Rendering `list` output and escaping control characters. |
| `src/config.js`, `src/errors.js` | Environment-driven limits; error classes that carry their exit code. |

### Id allocation

There were two reasonable ways to pick the next id:

1. **Highest existing id + 1.** This needs no extra state, but it reuses an id when you delete the newest todo. Delete todo 3, add a new one, and it also becomes 3, so an old `complete 3` in your shell history now acts on the wrong item.
2. **A persisted counter (`nextId`)** that only goes up.

This app uses the counter, so ids are never reused. Approach 1 survives as the fallback for files that have no `nextId` (bare arrays), and loading always raises `nextId` above the highest existing id. A hand-edited counter therefore can't produce duplicates.

### Writes are atomic and serialized

- **Atomic replace.** A write goes to a uniquely named temp file in the same directory, is flushed with `fsync`, then renamed over `todos.json`. A crash mid-write leaves the old file intact, and `list` never sees half a file.
- **Lock file.** `add`, `complete`, and `delete` read, modify, and write the file. Two commands running at once could otherwise both read the same state and one update would be lost. Each of these commands holds `todos.json.lock` for the whole cycle. The lock is created with an exclusive-create flag, which makes creation an atomic test-and-set. Waiting commands retry every 20 ms until `TODO_LOCK_TIMEOUT_MS`. `list` does not take the lock, since the atomic rename already guarantees it reads a complete file.
- **Abandoned locks.** A lock older than `TODO_STALE_LOCK_MS` is assumed to belong to a process that was killed mid-command, and is removed. Detection is by file age only, which is best-effort: if two waiting processes both judge the same lock stale at the same moment, one could remove the other's fresh lock. The window is a few milliseconds, and it only opens after a crash. The lock also assumes a local filesystem; exclusive create is not reliable on some network filesystems.

The test suite covers this directly: it launches parallel `add` processes and parallel `complete`/`delete` processes, then checks that none of the updates were lost.

### Input rules

- **Text** is trimmed and must be non-empty. It may not contain control characters (newlines, tabs, ESC, and so on). That keeps `list` to one line per todo and stops text from injecting terminal escape sequences. Length is counted in code points, so an emoji counts as one character, not two UTF-16 units.
- **Ids** must be decimal digits forming a safe integer ≥ 1. `1.5`, `1e2`, `0x1`, `-1`, `+1`, and non-ASCII digits are rejected. Leading zeros are allowed (`007` is 7).
- **Command names** are looked up in a `Map`, so inputs like `constructor` or `__proto__` are unknown commands, not object-prototype properties.
- Invalid input is rejected before the lock is taken or the file is read, so a bad argument gets a precise message even when the file is busy or damaged.

### Damaged files are never overwritten

If `todos.json` is not valid JSON or fails schema validation, every command stops with exit code 1. The message names the file and the problem, such as `todo at index 2 (id 5) has an invalid "completed"`. The file is not rewritten, so nothing is lost; fix it or move it aside. An empty file and a UTF-8 byte order mark are both tolerated. Unknown extra fields on a todo are kept on rewrite.

When `list` prints text from a hand-edited file that contains control characters, it shows them as visible `\uXXXX` escapes.

### Isolation

Each directory has its own `todos.json` and its own lock, so separate projects never share state or wait on each other.

## Development

```console
$ npm install        # dev dependencies (ESLint) only
$ npm test           # node --test "test/**/*.test.js"
$ npm run lint       # eslint .
$ npm run check      # lint, then test
```

Tests use the built-in `node:test` runner and create a fresh temp directory for each case.

| File | Level | Covers |
| --- | --- | --- |
| `test/todos.test.js` | Unit | State operations, text and id validation, no mutation of inputs |
| `test/format.test.js` | Unit | `list` rendering, alignment, ordering, escaping |
| `test/config.test.js` | Unit | Environment parsing and rejection of bad values |
| `test/storage.test.js` | Integration | Load/save round trips, schema validation, atomic writes, lock timeout and stale-lock recovery, permission errors |
| `test/cli.test.js` | Integration | Each command through `run()` against a real directory, help, and error reporting |
| `test/e2e.test.js` | End-to-end | Spawns `node index.js` for the full lifecycle, exit codes, stream separation, and closed-pipe handling |
| `test/edge-cases.test.js` | Edge cases | Missing or extra arguments, invalid and unknown ids, unicode, length limits, corrupt files, prototype-key commands, concurrent processes |

## Out of scope

Editing a todo's text, un-completing, priorities, due dates, acting on several ids at once, and a custom file location. `list` shows every todo; there are no filters.

