export function normalizeText(rawText, { maxLength = DEFAULT_MAX_TEXT_LENGTH } = {}) {
  if (typeof rawText !== 'string') {
    throw new ValidationError(`Todo text must be a string, got ${typeof rawText}.`);
  }
  const text = rawText.trim();
  if (text.length === 0) {
    throw new ValidationError('Todo text cannot be empty or only whitespace.');
  }
  if (CONTROL_CHARACTER.test(text)) {
    throw new ValidationError('Todo text must be a single line without control characters such as newlines or tabs.');
  }
