export const EXIT_CODES = Object.freeze({
  SUCCESS: 0,
  FAILURE: 1,
  USAGE: 2,
});

/**
 * Base class for expected failures. The CLI prints `message` without a stack
 * trace and exits with `exitCode`; anything else is treated as a bug.
 */
export class TodoError extends Error {
  constructor(message, { exitCode = EXIT_CODES.FAILURE, cause } = {}) {
    super(message, cause === undefined ? undefined : { cause });
    this.name = new.target.name;
    this.exitCode = exitCode;
  }
}

/** Wrong command shape: unknown command, missing or extra arguments. Usage is printed. */
export class UsageError extends TodoError {
  constructor(message, options = {}) {
    super(message, { ...options, exitCode: EXIT_CODES.USAGE });
  }
}

/** An argument has the right position but an unacceptable value, such as an id of "abc". */
export class ValidationError extends TodoError {
  constructor(message, options = {}) {
    super(message, { ...options, exitCode: EXIT_CODES.USAGE });
  }
}

/** The referenced todo does not exist. */
export class NotFoundError extends TodoError {}

/** todos.json (or its lock) could not be read, parsed, validated, or written. */
export class StorageError extends TodoError {}
const CONTROL_CHARACTER = /\p{Cc}/gu;

/**
 * Replaces control characters (newlines, tabs, ESC, C1 controls) with visible
 * `\uXXXX` escapes. Text written by `add` never contains them, but a
 * hand-edited todos.json might, and printing raw ESC sequences would let file
 * contents drive the terminal.
 */
export function escapeControlCharacters(text) {
  return text.replace(CONTROL_CHARACTER, (char) => `\\u${char.codePointAt(0).toString(16).padStart(4, '0')}`);
}

function pluralize(count, singular, plural) {
  return `${count} ${count === 1 ? singular : plural}`;
}

/** Renders one todo as `<id>. [x] <text>`, padding the id column to `idWidth` digits. */
export function formatTodoLine(todo, idWidth = String(todo.id).length) {
  const idLabel = `${todo.id}.`.padEnd(idWidth + 1);
  const status = todo.completed ? '[x]' : '[ ]';
  return `${idLabel} ${status} ${escapeControlCharacters(todo.text)}`;
}

/** Renders the `list` output: one line per todo in id order, then a done/pending summary. */
export function formatTodoList(todos) {
  if (todos.length === 0) {
    return 'No todos yet. Add one with: node index.js add "Buy groceries"';
  }

  const sorted = todos.toSorted((a, b) => a.id - b.id);
  const idWidth = sorted.reduce((width, todo) => Math.max(width, String(todo.id).length), 0);
  const doneCount = sorted.filter((todo) => todo.completed).length;
  const pendingCount = sorted.length - doneCount;

  const lines = sorted.map((todo) => formatTodoLine(todo, idWidth));
  lines.push('', `${pluralize(sorted.length, 'todo', 'todos')}: ${doneCount} done, ${pendingCount} pending`);
