import { execFile } from 'node:child_process';
import { mkdtemp, readFile, readdir, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { run } from '../../src/cli.js';

export const PROJECT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');
export const ENTRY_POINT = path.join(PROJECT_ROOT, 'index.js');

const CHILD_PROCESS_TIMEOUT_MS = 15_000;

/** Creates an isolated working directory; pair with `removeTempDir` in `afterEach`. */
export function makeTempDir() {
  return mkdtemp(path.join(tmpdir(), 'cli-todo-test-'));
}

export function removeTempDir(dir) {
  return rm(dir, { recursive: true, force: true });
}

/** Returns the parsed todos.json in `dir`, or `undefined` when the file does not exist. */
export async function readTodoFile(dir) {
  try {
    return JSON.parse(await readFile(path.join(dir, 'todos.json'), 'utf8'));
  } catch (error) {
    if (error.code === 'ENOENT') {
      return undefined;
    }
    throw error;
  }
}

export function listDir(dir) {
  return readdir(dir);
}

function createCollector() {
  const chunks = [];
  return {
    write(chunk) {
      chunks.push(String(chunk));
      return true;
    },
    text() {
      return chunks.join('');
    },
  };
}

/** Runs the CLI in-process with captured output. `options` are forwarded to `run`. */
export async function runInProcess(argv, options) {
  const stdout = createCollector();
  const stderr = createCollector();
  const code = await run(argv, { env: {}, ...options, stdout, stderr });
  return { code, stdout: stdout.text(), stderr: stderr.text() };
}

/** Spawns `node index.js ...args` in `cwd` and resolves with its exit code and output. */
export function runNode(args, { cwd, env = {} }) {
  return new Promise((resolve, reject) => {
    execFile(
      process.execPath,
      [ENTRY_POINT, ...args],
      { cwd, env: { PATH: process.env.PATH, ...env }, timeout: CHILD_PROCESS_TIMEOUT_MS },
      (error, stdout, stderr) => {
        if (error && typeof error.code !== 'number') {
          reject(new Error(`Failed to run CLI with args ${JSON.stringify(args)}: ${error.message}`, { cause: error }));
          return;
        }
        resolve({ code: error ? error.code : 0, stdout, stderr });
      },
    );
  });
}
